#!/usr/bin/env node
/**
 * Post-install check: what the plugin has been doing, and what the ball shows.
 *
 *   node test/status.mjs
 *
 * Reads the plugin's own JSONL evidence log (tool calls → pushes, plus how many
 * tool schemas got the required field) and the live ball state over the app's
 * control bridge, so one command answers "did it actually run, and is the line
 * on the ball".
 */

import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const logFile = process.argv[2]
    || process.env.BALL_SUMMARY_LOG
    || join(process.env.DSH_HOME || join(homedir(), '.dsh'), 'ball-summary', 'ball-summarizer.jsonl');

let entries = [];
try {
    entries = readFileSync(logFile, 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line));
} catch {
    console.log(`还没有日志：${logFile}`);
    console.log('说明插件没被加载，或者还没发生操作。先确认 plugin_manager 里 ball-summarizer 这一行是 applied（新装 bundle 需要重启 dsh web 才会挂上）。');
    process.exit(1);
}

const count = (event) => entries.filter((entry) => entry.ev === event).length;
const last = (event) => entries.filter((entry) => entry.ev === event).pop();
const ops = entries.filter((entry) => entry.ev === 'op');
const pushes = entries.filter((entry) => entry.ev === 'push');
const withField = ops.filter((entry) => entry.ballDoing);
const missing = ops.filter((entry) => !entry.ballDoing);
const rate = (rows) => rows.length === 0 ? '—' : `${Math.round((rows.filter((entry) => entry.ballDoing).length / rows.length) * 100)}%`;

console.log(`日志 ${logFile}`);
console.log(`  工具调用 ${ops.length} 次（带 ball_doing ${withField.length} 次，缺 ${missing.length} 次）`
    + ` · 状态推送 ${pushes.length} 次（心跳 ${pushes.filter((entry) => entry.note === 'heartbeat').length}，失败 ${count('push-error')}）`
    + ` · 模型调用 0 次`);
// The one line to read when judging whether the required field actually holds.
console.log(`  合规率：全部 ${rate(ops)} · 最近 50 次 ${rate(ops.slice(-50))} · 最近 10 次 ${rate(ops.slice(-10))}`
    + `（缺字段时球上降级成「正在执行 <工具名>」）`);
if (missing.length) console.log(`  最近几次缺字段：${missing.slice(-3).map((entry) => `${entry.tool}(#${entry.n})`).join(' ')}`);
if (count('schema')) console.log(`  工具 schema 加字段：最近一次 ${last('schema').tools} 个工具（field=${last('schema').field} required=${last('schema').required}）`);
if (ops.length) console.log(`  最近工具调用：${ops.slice(-3).map((entry) => `${entry.tool}${entry.ballDoing ? `(${entry.ballDoing})` : '(缺字段)'}`).join(' ')}`);
if (pushes.length) {
    console.log('  最近推送：');
    for (const entry of pushes.slice(-5)) console.log(`    ${String(entry.phase).padEnd(5)} ${String(entry.note).padEnd(11)} ${entry.text}`);
}

const url = process.env.DSH_ANDROID_BRIDGE_URL;
const token = process.env.DSH_ANDROID_BRIDGE_TOKEN;
if (!url || !token) {
    console.log('  （没有 DSH_ANDROID_BRIDGE_URL/TOKEN，跳过球的实时状态）');
    process.exit(0);
}
try {
    const response = await fetch(`${url.replace(/\/+$/u, '')}/ball/state`, { headers: { 'X-Dsh-Token': token } });
    console.log(`  GET /ball/state 原始响应：${await response.text()}`);
} catch (error) {
    console.log(`  球的状态读不到：${error && error.message ? error.message : error}`);
}
